$steps += @{ Name = 'T16 Site logo r12: thumbnail'; Title = 'Set the site thumbnail to the new logo'; Dir = 'T16'; File = '90161Z-logo-512.png'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You set the site thumbnail to the new 90-161.Z logo. The next card sets the header logo. About 3 minutes.'; Kind = 'guide'; Guide = @('1. Select "Open in browser" above.', '2. At the top right of the site, select the gear "Settings".', '3. Select "Change the look".', '4. Select "Header".', '5. Under "Site logo thumbnail", select "Change".', '6. In the box "File name", press Ctrl+V (the file path is on the clipboard).', '7. Select "Open".', 'If the page is not your site: type your site address in the browser address bar.', 'If there is no "Site logo thumbnail" box: select "It failed".'); Url = 'https://usaf.dps.mil/sites/<your-site>'; UrlConfig = '90161Z-site.txt'; Marker = '90161Z-T16-thumb-set.txt'; Estimate = 180; DoneText = ''; DoneLog = 'Confirmed by you: set the thumbnail.'; Makes = @(); After = @(); Optional = $false; Help = '' }
$steps += @{ Name = 'T16 Site logo r12: header logo'; Title = 'Set the site header logo to the new logo'; Dir = 'T16'; File = '90161Z-logo-512.png'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You set the header logo of the site to the new 90-161.Z logo and save both. The next step reads the logo back. About 3 minutes.'; Kind = 'guide'; Guide = @('1. Under "Site logo", select "Change".', '2. In the box "File name", press Ctrl+V (the file path is on the clipboard).', '3. Select "Open".', '4. Select "Save".', '5. Look at the top left of the site: the new logo must show.', 'If "Save" stays gray: select "It failed".'); Url = ''; UrlConfig = ''; Marker = '90161Z-T16-logo-set.txt'; Estimate = 180; DoneText = ''; DoneLog = 'Confirmed by you: set the header logo.'; Makes = @(); After = @('T16 Site logo r12: thumbnail'); Optional = $false; Help = ''; Answers = @(@{ Key = 'logo-header'; Prompt = 'After Save, what did the site header show at the top left?'; Kind = 'pick'; Choices = @('The new 90-161.Z logo', 'The old logo', 'No logo', 'Save failed') }, @{ Key = 'logo-thumb'; Prompt = 'Did the thumbnail take the new logo?'; Kind = 'pick'; Choices = @('Yes', 'No', 'There was no thumbnail box') }) }
$steps += @{ Name = 'T16 Read the site logo back r12'; Title = 'Read the site logo back'; Dir = 'T16'; File = '90161Z-T16-site-setup-r12.ps1'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 10; Args = '-LogoOnly'; Note = 'Signs in (CAC). Reads the header logo of the site back. Changes nothing on the site.'; Kind = 'script'; Guide = @(); Url = ''; UrlConfig = ''; Marker = ''; Estimate = 60; DoneText = ''; DoneLog = ''; Makes = @(); After = @('T16 Site logo r12: header logo'); Optional = $false; Help = 'Send the results as they are. The step can be run again.' }
