$steps += @{ Name = 'T21 Second person r5'; Title = 'Ask the second person to add a row'; Dir = 'T21'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You ask the person you added to Visitors to add one row with the form link. A colleague is free today. About 5 minutes.'; Kind = 'guide'; Guide = @('1. Open Teams.', '2. Select "Chat".', '3. Select "New chat".', '4. In the box "To", type the e-mail address you gave RADE for the second person.', '5. Select the chat box.', '6. Press Ctrl+V (the form link is on the clipboard).', '7. In the chat box, type: Open the link, type T4a in Title, select Save, tell me what you saw.', '8. Press Enter.', '9. Wait for the reply: the row saved, or no permission.', 'If nobody replies: select "Skip".'); Url = ''; UrlConfig = ''; Marker = '90161Z-T21-second-person.txt'; Estimate = 300; DoneText = ''; DoneLog = 'Confirmed by you: second person.'; Makes = @(); After = @('T21 Add the second person r5'); Optional = $false; Help = ''; Answers = @(@{ Key = 't4-second'; Prompt = 'What did the second person see?'; Kind = 'pick'; Choices = @('The row was saved', 'No permission', 'The link did not open', 'Something else') }) }
$steps += @{ Name = 'T21 Button flow by hand r5: make a solution'; Title = 'Make a solution for the button flow'; Dir = 'T21'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You make an empty solution "90-161.Z probe button" for one flow that you build by hand. About 4 minutes.'; Kind = 'guide'; Guide = @('1. Select "Open in browser" above.', '2. If Power Automate asks you to sign in: sign in with your CAC.', '3. On the left, select "Solutions" (it can be under "More").', '4. Select "New solution".', '5. In the box "Display name", type: 90-161.Z probe button', '6. In the box "Publisher", select any publisher in the list.', '7. Select "Create".', '8. Look at the list: the solution "90-161.Z probe button" must be there.', 'If a box or button is missing: select "It failed".'); Url = 'https://make.powerautomate.appsplatform.us/'; UrlConfig = '90161Z-flow-portal.txt'; Marker = '90161Z-T21-button-solution.txt'; Estimate = 240; DoneText = ''; DoneLog = 'Confirmed by you: made the button solution.'; Makes = @(); After = @(); Optional = $false; Help = '' }
$steps += @{ Name = 'T21 Button flow by hand r5: make the flow'; Title = 'Make the button flow'; Dir = 'T21'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You make a new flow in the solution with the trigger "For a selected item". About 4 minutes.'; Kind = 'guide'; Guide = @('1. Select the solution "90-161.Z probe button".', '2. On the left, select "Objects".', '3. Select "New".', '4. Select "Automation".', '5. Select "Cloud flow".', '6. Select "Instant".', '7. In the box "Flow name", type: 90161Z T21 Probe Button hand r5', '8. In the search box of the trigger list, type: For a selected item', '9. Select the trigger "For a selected item" (SharePoint).', '10. Select "Create".', 'If no trigger "For a selected item" is listed: select "It failed".'); Url = ''; UrlConfig = ''; Marker = '90161Z-T21-button-trigger.txt'; Estimate = 300; DoneText = ''; DoneLog = 'Confirmed by you: set the trigger.'; Makes = @(); After = @('T21 Button flow by hand r5: make a solution'); Optional = $false; Help = '' }
